ListNode* slow = head;
ListNode* fast = head;
while (fast && fast->next) {
    slow = slow->next;
    fast = fast->next->next;
    if (slow == fast) {
        // cycle or meeting point found
        break;
    }
}

ListNode* prev = nullptr;
ListNode* curr = head;
while (curr) {
    ListNode* nextNode = curr->next;
    curr->next = prev;
    prev = curr;
    curr = nextNode;
}
return prev;

ListNode dummy(0);
ListNode* tail = &dummy;
while (head) {
    tail->next = head;
    tail = tail->next;
    head = head->next;
}
tail->next = nullptr;
return dummy.next;

unordered_map<Node*, Node*> copy;
for (Node* cur = head; cur; cur = cur->next) {
    copy[cur] = new Node(cur->val);
}
for (Node* cur = head; cur; cur = cur->next) {
    copy[cur]->next = copy[cur->next];
    copy[cur]->random = copy[cur->random];
}
return copy[head];

priority_queue<ListNode*, vector<ListNode*>, Compare> pq;
for (ListNode* list : lists) {
    if (list) pq.push(list);
}
ListNode dummy(0);
ListNode* tail = &dummy;
while (!pq.empty()) {
    ListNode* node = pq.top();
    pq.pop();
    tail->next = node;
    tail = tail->next;
    if (node->next) pq.push(node->next);
}
return dummy.next;
